const result = $input.first().json;
let seoData;
try { seoData = typeof result.seo_data === 'string' ? JSON.parse(result.seo_data) : result.seo_data; } catch(e) { seoData = {}; }

const prompt = `You are an expert SEO consultant. Analyze this SEO data and provide actionable recommendations.

Current SEO Data:
- Rankings: ${JSON.stringify((seoData.rankings || []).slice(0, 10))}
- Backlinks: ${JSON.stringify(seoData.backlinks || {})}
- Health Issues: ${JSON.stringify((seoData.health_issues || []).slice(0, 3))}
- Top GSC Queries: ${JSON.stringify((seoData.top_pages_gsc || []).slice(0, 5))}

Provide:
1. Top 5 priority actions this week (specific, actionable)
2. Quick wins (things that can be done in <1 hour)
3. Content recommendations (topics to write about)
4. Technical fixes needed

Format as JSON with keys: priority_actions (array of {action, impact, effort}), quick_wins (array), content_ideas (array of {topic, keyword, reason}), technical_fixes (array)`;

return [{ json: { prompt, seo_data: seoData } }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';

let recommendations = {};
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  recommendations = JSON.parse(jsonMatch ? jsonMatch[0] : '{}');
} catch(e) {
  recommendations = { priority_actions: [{ action: 'Review SEO data manually', impact: 'high', effort: 'medium' }], quick_wins: ['Check for broken links'], content_ideas: [], technical_fixes: [] };
}

return [{ json: { recommendations, generated_at: new Date().toISOString() } }];

